export function getProductDescription(productOrDesc, lang = "uk") {
    if (!productOrDesc) return "";
    if (typeof productOrDesc === "object") {
        if (lang === "uk") {
            if (productOrDesc.descriptionUk) return productOrDesc.descriptionUk;
            if (productOrDesc.id && PRODUCT_DESCRIPTIONS_UK[productOrDesc.id]) return PRODUCT_DESCRIPTIONS_UK[productOrDesc.id];
            if (productOrDesc.description && PRODUCT_DESCRIPTIONS_UK[productOrDesc.description]) return PRODUCT_DESCRIPTIONS_UK[productOrDesc.description];
            return productOrDesc.description || "";
        }
        return productOrDesc.descriptionEn || productOrDesc.description || "";
    }
    if (lang === "en") return productOrDesc;
    return PRODUCT_DESCRIPTIONS_UK[productOrDesc] || productOrDesc;
}
